if([word,fixture,core].some(r=>r.status!=='passed')||Object.values(word.assertions).some(v=>v!==true)||Object.values(fixture.assertions).some(v=>v!==true)||before.assertions.disabledStateVerified!==false||core.checks.length!==22)throw Error('NATIVE_EVIDENCE_REQUIRED');
